// The program the Motif view starts from when it has nothing else to show:
// short enough to read in one go, and touching each part of the language — a
// song, instruments, lanes, sections, chords that move as little as they can,
// a random walk keyed by the song's seed, a transformation (the walk played
// backwards), a phrase of music named and looped, and chance in the drums.
// test/node/motif-music.test.js builds it.

export const MOTIF_EXAMPLE = `tml 2
// An example to start from: eight bars in 19-tone equal temperament, half
// written down and half generated by rules. Change the seed and build again
// (Ctrl+Enter) for another tune. Docs → Motif Language has the whole language.
//
// A program says what the song is: every line on its own is part of the
// music, names can be used before the line that defines them, and nothing,
// once named, changes.

song {
  title: "Motif example"
  tuning: "19-TET"
  tempo: 96
  speed: 6
  bars: 8
  bar_rows: 16
  beat_rows: 4
  global_volume: 255
  mixing_volume: 160
  seed: 19            // the same seed always builds the same song
}

instrument PIANO { bank: 0, program: 0 }
instrument PAD   { bank: 0, program: 89 }
instrument BASS  { bank: 0, program: 33 }
instrument KIT   { bank: 128, program: 0 }

lane tune { inst: PIANO, pan: $90 }
lane pad1 { inst: PAD, pan: $60 }
lane pad2 { inst: PAD, pan: $80 }
lane pad3 { inst: PAD, pan: $A0 }
lane bass { inst: BASS }
lane kick { inst: KIT }
lane hat  { inst: KIT, pan: $A8, jitter: 4 }

section "walk" 1..4
section "back" 5..8

// ── harmony: a chord a bar. In 19-TET a major third is 6 steps, a minor
// third 5 and a fifth 11.
fn triad(root, third) => { root: degree(root), ivs: [0, third, 11] }
let CHORDS = [triad("C", 6), triad("A", 5), triad("F", 6), triad("G", 6)]
fn chord(bar) => CHORDS[(bar - 1) % 4]
let PADS = [pad1, pad2, pad3]
// each bar's voicing moves each note as little as it can from the bar before
let HELD = scan(1..8, notes("C4 E4 G4"), fn(held, bar) => nearest_chord(held, chord(bar), 'G3', 'G4'))
for bar in 1..8 {
  for i, p in HELD[bar - 1] { hit(PADS[i], at(bar), p, 26) }
  let root = period() * 2 + chord(bar).root       // the root, two periods up from C0
  hit(bass, at(bar), root, 50)
  hit(bass, at(bar, 8), root + 11, 40)
}

// ── the tune: a random walk up and down the major scale, a quarter note a
// step, and then the same walk backwards so the second half answers the
// first. Each step is chosen by choose(…, "walk", n): the same keys always
// make the same choice, until the seed changes.
let SCALE = notes("C5 D5 E5 F5 G5 A5 B5 C6")
let STEPS = [choose([-2, -1, -1, 1, 1, 2], "walk", n) for n in 1..16]
let WALK = [SCALE[i] for i in scan(STEPS, 4, fn(i, step) => clamp(i + step, 0, len(SCALE) - 1))]
for n, p in WALK + reverse(WALK) {
  hit(tune, n * 4, p, if n % 4 == 0 then 48 else 38)
}

// ── drums: a bar of kicks, named once and played in every bar; now and then
// one kick more; hats by a loose hand
let KICKS = stack(hit(kick, 0, midi(36), 50), hit(kick, 8, midi(36), 46))
loop(KICKS, 8, every: 16)
for bar in 1..8 if chance(0.4, "kick", bar) { hit(kick, at(bar, 14), midi(36), 34) }
for bar in 1..8 {
  for r in 0..<16 by 2 { hit(hat, at(bar, r), midi(42), random_int(18, 30, "hat", bar, r) + (if r % 4 == 0 then 6 else 0)) }
}
`;
